const lamp = {
  level: 1,
  brighter() {
    this.level *= 2;
  },
};

const desk = Object.create(lamp);
const hall = Object.create(lamp);

desk.brighter();
desk.brighter();
lamp.brighter();
hall.brighter();

console.log(desk.level, hall.level, lamp.level);
console.log(Object.hasOwn(hall, "level"));
